895		}
896		if got.Status != ExchangeRejected || got.Receipt == nil || got.Receipt.Reason != "重开前拒绝" {
897			t.Fatalf("receipt lost: %+v", got)
898		}
899		if len(got.Package.Records) != 1 || got.Package.Records[0].VersionID != v1.ID ||
900			got.Package.Records[0].Content != "包内v1" {
901			t.Fatalf("frozen package lost: %+v", got.Package.Records)
902		}
903	
904		// 同请求号重试仍返回原交换，不新增审计。
905		auditBefore := len(mustAudit(t, s2, p.ID))
906		retry, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
