	if _, err := f.s.GetExchange(doc, f.pid, xs1.ID); err != nil {
		t.Fatalf("get after deactivate: %v", err)
	}
	if xs, err := f.s.ListExchanges(doc, f.pid); err != nil || len(xs) != 2 {
		t.Fatalf("list after deactivate: %d %v", len(xs), err)
	}
